package com.loopers.infrastructure.queue
import com.loopers.config.redis.RedisConfig;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.core.io.ClassPathResource;import org.springframework.data.redis.core.*;import org.springframework.data.redis.core.script.DefaultRedisScript;import org.springframework.stereotype.Component
// Hides: Lua atomicity, Redis key layout, and terminal slot release.
@Component class RedisAdmissionStore(@Qualifier(RedisConfig.REDIS_TEMPLATE_MASTER)private val redis:RedisTemplate<String,String>){private val script=DefaultRedisScript<Long>().also{it.setLocation(ClassPathResource("redis/admission.lua"));it.resultType=Long::class.java};fun admit(id:String,capacity:Int)=redis.execute(script,listOf(KEY),id,capacity.toString())==1L;fun terminal(id:String){redis.opsForHash<String,String>().delete(KEY,id)};fun pending()=redis.opsForHash<String,String>().size(KEY);fun clear(){redis.delete(KEY)};companion object{const val KEY="w8:admission:pending"}}
